const items = $input.all();
const weekEnd = new Date().toISOString().split('T')[0];

let twitter = {likes: 0, retweets: 0, replies: 0, posts: 0};
let instagram = {likes: 0, comments: 0, posts: 0};
let linkedin = {likes: 0, shares: 0, comments: 0, posts: 0};

for (const item of items) {
  const data = item.json.data || item.json.elements || [];
  if (Array.isArray(data)) {
    for (const entry of data) {
      if (entry.public_metrics) {
        // Twitter
        twitter.likes += entry.public_metrics.like_count || 0;
        twitter.retweets += entry.public_metrics.retweet_count || 0;
        twitter.replies += entry.public_metrics.reply_count || 0;
        twitter.posts++;
      } else if (entry.like_count !== undefined) {
        // Instagram
        instagram.likes += entry.like_count || 0;
        instagram.comments += entry.comments_count || 0;
        instagram.posts++;
      }
    }
  }
  // LinkedIn stats
  if (item.json.elements) {
    for (const el of item.json.elements) {
      const stats = el.totalShareStatistics || {};
      linkedin.likes += stats.likeCount || 0;
      linkedin.shares += stats.shareCount || 0;
      linkedin.comments += stats.commentCount || 0;
      linkedin.posts++;
    }
  }
}

const totalEngagement = twitter.likes + twitter.retweets + twitter.replies + instagram.likes + instagram.comments + linkedin.likes + linkedin.shares + linkedin.comments;

return [{
  json: {
    week_ending: weekEnd,
    twitter_likes: twitter.likes,
    twitter_retweets: twitter.retweets,
    twitter_replies: twitter.replies,
    twitter_posts: twitter.posts,
    instagram_likes: instagram.likes,
    instagram_comments: instagram.comments,
    instagram_posts: instagram.posts,
    linkedin_likes: linkedin.likes,
    linkedin_shares: linkedin.shares,
    linkedin_comments: linkedin.comments,
    linkedin_posts: linkedin.posts,
    total_engagement: totalEngagement,
    best_platform: twitter.likes >= instagram.likes && twitter.likes >= linkedin.likes ? 'Twitter' : instagram.likes >= linkedin.likes ? 'Instagram' : 'LinkedIn'
  }
}];

